-- Correct snapshots created on/after the effective date before deployment.
-- Clock times, photos, attendance decisions and dates before 26 September stay untouched.
CREATE TEMP TABLE master_record_changes AS
SELECT a."id", a."userId", a."policyVersion", a."scheduledStartAt", a."scheduledEndAt", a."extraTimeCutoff", a."shiftDurationMinutes", a."unpaidBreakMinutes", a."latePenaltyActive", a."earlyPenaltyActive",
COALESCE(s."startsAt", CAST(strftime('%s', a."workDate" || 'T00:00:00+05:30') AS INTEGER)*1000 + json_extract(u."masterScheduleJson", '$."' || strftime('%w', a."workDate") || '".start')*60000) AS newStart,
COALESCE(s."endsAt", CAST(strftime('%s', a."workDate" || 'T00:00:00+05:30') AS INTEGER)*1000 + (json_extract(u."masterScheduleJson", '$."' || strftime('%w', a."workDate") || '".start')+json_extract(u."masterScheduleJson", '$."' || strftime('%w', a."workDate") || '".duration'))*60000) AS newEnd,
COALESCE(json_extract(u."masterScheduleJson", '$."' || strftime('%w', a."workDate") || '".unpaidBreak'),0) AS newBreak
FROM "AttendanceRecord" a JOIN "User" u ON u."id"=a."userId"
LEFT JOIN "ScheduledShift" s ON s."userId"=a."userId" AND s."workDate"=a."workDate"
WHERE a."workDate">='2026-09-26' AND a."policyVersion"<>3 AND u."masterScheduleJson" IS NOT NULL
AND (s."id" IS NOT NULL OR json_extract(u."masterScheduleJson", '$."' || strftime('%w', a."workDate") || '"') IS NOT NULL);
INSERT INTO "PolicyAudit" ("id","entityId","userId","actorId","actorName","action","beforeJson","afterJson","createdAt")
SELECT 'master-20260926-' || "id", "id", "userId", 'SYSTEM', 'Master timetable rollout', 'MASTER_POLICY_APPLIED',
json_object('policyVersion',"policyVersion",'scheduledStartAt',"scheduledStartAt",'scheduledEndAt',"scheduledEndAt",'shiftDurationMinutes',"shiftDurationMinutes",'unpaidBreakMinutes',"unpaidBreakMinutes",'extraTimeCutoff',"extraTimeCutoff",'latePenaltyActive',"latePenaltyActive",'earlyPenaltyActive',"earlyPenaltyActive"),
json_object('policyVersion',3,'scheduledStartAt',newStart,'scheduledEndAt',newEnd,'shiftDurationMinutes',(newEnd-newStart)/60000,'unpaidBreakMinutes',newBreak,'latePenaltyActive',0,'earlyPenaltyActive',0),
CAST(strftime('%s','now') AS INTEGER)*1000 FROM master_record_changes;
UPDATE "AttendanceRecord" SET "policyVersion"=3,
"scheduledStartAt"=(SELECT newStart FROM master_record_changes c WHERE c.id="AttendanceRecord".id),
"scheduledEndAt"=(SELECT newEnd FROM master_record_changes c WHERE c.id="AttendanceRecord".id),
"extraTimeCutoff"=(SELECT newEnd FROM master_record_changes c WHERE c.id="AttendanceRecord".id),
"shiftDurationMinutes"=(SELECT (newEnd-newStart)/60000 FROM master_record_changes c WHERE c.id="AttendanceRecord".id),
"unpaidBreakMinutes"=(SELECT newBreak FROM master_record_changes c WHERE c.id="AttendanceRecord".id),
"latePenaltyActive"=0,"earlyPenaltyActive"=0,"updatedAt"=CAST(strftime('%s','now') AS INTEGER)*1000
WHERE id IN (SELECT id FROM master_record_changes);
DROP TABLE master_record_changes;
